import{_ as t,o as a,c as i,a4 as n}from"./chunks/framework.BWWfBZka.js";const h=JSON.parse('{"title":"36 Estudios de Caso Prácticos (Case Studies)","description":"","frontmatter":{},"headers":[],"relativePath":"es/04_Case_Studies.md","filePath":"es/04_Case_Studies.md","lastUpdated":1788997660000}'),o={name:"es/04_Case_Studies.md"};function r(s,e,l,d,g,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="_36-estudios-de-caso-practicos-case-studies" tabindex="-1">36 Estudios de Caso Prácticos (Case Studies) <a class="header-anchor" href="#_36-estudios-de-caso-practicos-case-studies" aria-label="Permalink to &quot;36 Estudios de Caso Prácticos (Case Studies)&quot;">​</a></h1><blockquote><p><em>Problemas resueltos paso a paso: preguntas de aclaración, componentes, cuellos de botella y relances.</em></p></blockquote><hr><p><strong>Total de Casos</strong>: 36</p><h2 id="📑-indice-rapido-de-problemas" tabindex="-1">📑 Índice Rápido de Problemas <a class="header-anchor" href="#📑-indice-rapido-de-problemas" aria-label="Permalink to &quot;📑 Índice Rápido de Problemas&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th style="text-align:left;">Problema</th><th style="text-align:center;">Nivel</th><th style="text-align:left;">Cuello de Botella Real</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;"><a href="#_1-design-a-url-shortener-tinyurl">Design a URL shortener (TinyURL)</a></td><td style="text-align:center;"><code>Warm-up</code></td><td style="text-align:left;">Key generation without collisions at scale, and the read-heavy redirect path</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;"><a href="#_2-design-a-rate-limiter">Design a rate limiter</a></td><td style="text-align:center;"><code>Warm-up</code></td><td style="text-align:left;">Distributed counting without a race condition, and Redis becoming the bottleneck</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;"><a href="#_3-design-pastebin">Design Pastebin</a></td><td style="text-align:center;"><code>Warm-up</code></td><td style="text-align:left;">Storing large text efficiently and separating blob from metadata</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;"><a href="#_4-design-a-key-value-store">Design a key-value store</a></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Partitioning, replication and the consistency versus availability choice</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;"><a href="#_5-design-a-web-crawler">Design a web crawler</a></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Politeness (not overwhelming a host) and duplicate URL detection at billions of scale</td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;"><a href="#_6-design-a-notification-system">Design a notification system</a></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Third-party provider failure and avoiding duplicate sends</td></tr><tr><td style="text-align:center;">7</td><td style="text-align:left;"><a href="#_7-design-a-news-feed-facebook-twitter">Design a news feed (Facebook, Twitter)</a></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Fan-out on write versus read, and celebrity users with 100 million followers</td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;"><a href="#_8-design-a-chat-system-whatsapp-messenger">Design a chat system (WhatsApp, Messenger)</a></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Maintaining millions of persistent connections and message ordering</td></tr><tr><td style="text-align:center;">9</td><td style="text-align:left;"><a href="#_9-design-a-search-autocomplete-system">Design a search autocomplete system</a></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Sub-100ms latency and keeping the trie updated without downtime</td></tr><tr><td style="text-align:center;">10</td><td style="text-align:left;"><a href="#_10-design-a-video-streaming-service-youtube-netflix">Design a video streaming service (YouTube, Netflix)</a></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Transcoding cost and CDN strategy; storage and bandwidth dominate the bill</td></tr><tr><td style="text-align:center;">11</td><td style="text-align:left;"><a href="#_11-design-a-ride-hailing-service-uber-ola">Design a ride-hailing service (Uber, Ola)</a></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Real-time geospatial matching and high-frequency location updates</td></tr><tr><td style="text-align:center;">12</td><td style="text-align:left;"><a href="#_12-design-a-food-delivery-system-swiggy-zomato">Design a food delivery system (Swiggy, Zomato)</a></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Peak-hour load concentration and three-party state consistency</td></tr><tr><td style="text-align:center;">13</td><td style="text-align:left;"><a href="#_13-design-a-payment-system">Design a payment system</a></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Exactly-once semantics with money, and reconciliation with external providers</td></tr><tr><td style="text-align:center;">14</td><td style="text-align:left;"><a href="#_14-design-a-ticket-booking-system-bookmyshow">Design a ticket booking system (BookMyShow)</a></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Preventing double-booking under extreme concurrency at a popular release</td></tr><tr><td style="text-align:center;">15</td><td style="text-align:left;"><a href="#_15-design-a-distributed-cache">Design a distributed cache</a></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Hot key distribution and invalidation across nodes</td></tr><tr><td style="text-align:center;">16</td><td style="text-align:left;"><a href="#_16-design-a-distributed-message-queue-kafka">Design a distributed message queue (Kafka)</a></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Ordering versus parallelism, and rebalancing without duplicate processing</td></tr><tr><td style="text-align:center;">17</td><td style="text-align:left;"><a href="#_17-design-google-docs-collaborative-editor">Design Google Docs (collaborative editor)</a></td><td style="text-align:center;"><code>Expert</code></td><td style="text-align:left;">Real-time conflict resolution with concurrent edits</td></tr><tr><td style="text-align:center;">18</td><td style="text-align:left;"><a href="#_18-design-a-distributed-file-storage-dropbox-drive">Design a distributed file storage (Dropbox, Drive)</a></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Efficient delta sync and block-level deduplication</td></tr><tr><td style="text-align:center;">19</td><td style="text-align:left;"><a href="#_19-design-a-proximity-service-yelp-nearby-places">Design a proximity service (Yelp, nearby places)</a></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Geospatial indexing with wildly uneven density between cities and countryside</td></tr><tr><td style="text-align:center;">20</td><td style="text-align:left;"><a href="#_20-design-a-metrics-and-monitoring-system">Design a metrics and monitoring system</a></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Write volume and cardinality explosion; downsampling strategy</td></tr><tr><td style="text-align:center;">21</td><td style="text-align:left;"><a href="#_21-design-a-logging-and-search-system-elk">Design a logging and search system (ELK)</a></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Indexing cost at volume and hot versus cold storage tiering</td></tr><tr><td style="text-align:center;">22</td><td style="text-align:left;"><a href="#_22-design-an-ad-click-aggregation-system">Design an ad click aggregation system</a></td><td style="text-align:center;"><code>Expert</code></td><td style="text-align:left;">Exactly-once counting with money attached, plus late and duplicate events</td></tr><tr><td style="text-align:center;">23</td><td style="text-align:left;"><a href="#_23-design-a-recommendation-system">Design a recommendation system</a></td><td style="text-align:center;"><code>Expert</code></td><td style="text-align:left;">Serving latency with a large model, and the cold-start problem</td></tr><tr><td style="text-align:center;">24</td><td style="text-align:left;"><a href="#_24-design-a-stock-exchange-trading-system">Design a stock exchange / trading system</a></td><td style="text-align:center;"><code>Expert</code></td><td style="text-align:left;">Deterministic ordering at microsecond latency, and absolute correctness</td></tr><tr><td style="text-align:center;">25</td><td style="text-align:left;"><a href="#_25-design-a-distributed-job-scheduler">Design a distributed job scheduler</a></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Ensuring a job runs exactly once across many scheduler instances</td></tr><tr><td style="text-align:center;">26</td><td style="text-align:left;"><a href="#_26-design-a-leaderboard-system">Design a leaderboard system</a></td><td style="text-align:center;"><code>Core</code></td><td style="text-align:left;">Ranking millions of users in real time without recomputing</td></tr><tr><td style="text-align:center;">27</td><td style="text-align:left;"><a href="#_27-design-an-api-rate-limited-public-api-platform">Design an API rate-limited public API platform</a></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Per-tenant quota enforcement across distributed gateways</td></tr><tr><td style="text-align:center;">28</td><td style="text-align:left;"><a href="#_28-design-a-urlcontent-moderation-system">Design a URL/content moderation system</a></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Balancing false positives against latency, plus the human review bottleneck</td></tr><tr><td style="text-align:center;">29</td><td style="text-align:left;"><a href="#_29-design-an-e-commerce-system-amazon-flipkart">Design an e-commerce system (Amazon, Flipkart)</a></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Inventory consistency during a flash sale and search at catalogue scale</td></tr><tr><td style="text-align:center;">30</td><td style="text-align:left;"><a href="#_30-design-a-hotel-or-flight-booking-system">Design a hotel or flight booking system</a></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Inventory held across third-party suppliers you do not control</td></tr><tr><td style="text-align:center;">31</td><td style="text-align:left;"><a href="#_31-design-a-social-media-platform-instagram">Design a social media platform (Instagram)</a></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Media storage and delivery cost, plus feed generation for varied follower counts</td></tr><tr><td style="text-align:center;">32</td><td style="text-align:left;"><a href="#_32-design-a-url-based-analytics-system-google-analytics">Design a URL-based analytics system (Google Analytics)</a></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Ingestion at very high write rates with flexible aggregation queries</td></tr><tr><td style="text-align:center;">33</td><td style="text-align:left;"><a href="#_33-design-a-code-deployment-system">Design a code deployment system</a></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Safe progressive rollout with automated rollback on failure</td></tr><tr><td style="text-align:center;">34</td><td style="text-align:left;"><a href="#_34-design-a-url-shortener-at-twitter-scale-deep-dive">Design a URL shortener at Twitter scale (deep dive)</a></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Global latency and key generation across regions without coordination</td></tr><tr><td style="text-align:center;">35</td><td style="text-align:left;"><a href="#_35-design-an-online-judge-coding-platform">Design an online judge / coding platform</a></td><td style="text-align:center;"><code>Advanced</code></td><td style="text-align:left;">Secure code sandboxing and contest-start load spikes</td></tr><tr><td style="text-align:center;">36</td><td style="text-align:left;"><a href="#_36-design-an-llm-inference-serving-platform">Design an LLM inference serving platform</a></td><td style="text-align:center;"><code>Expert</code></td><td style="text-align:left;">GPU utilisation through batching, and cost per request</td></tr></tbody></table><hr><h2 id="🛠️-analisis-detallado-de-casos" tabindex="-1">🛠️ Análisis Detallado de Casos <a class="header-anchor" href="#🛠️-analisis-detallado-de-casos" aria-label="Permalink to &quot;🛠️ Análisis Detallado de Casos&quot;">​</a></h2><h3 id="_1-design-a-url-shortener-tinyurl" tabindex="-1">1. Design a URL shortener (TinyURL) <a class="header-anchor" href="#_1-design-a-url-shortener-tinyurl" aria-label="Permalink to &quot;1. Design a URL shortener (TinyURL)&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Warm-up</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Read:write ratio, custom aliases, expiry, analytics, URL length</li><li>🧱 <strong>Componentes Clave</strong>: API layer, key generation service, KV store, cache, redirect service, analytics pipeline</li><li>⚡ <strong>Cuello de Botella Real</strong>: Key generation without collisions at scale, and the read-heavy redirect path</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: How do you avoid collisions? What if two servers generate the same key? How do you handle 100:1 reads?</li></ul><hr><h3 id="_2-design-a-rate-limiter" tabindex="-1">2. Design a rate limiter <a class="header-anchor" href="#_2-design-a-rate-limiter" aria-label="Permalink to &quot;2. Design a rate limiter&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Warm-up</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Per user or per IP, distributed or single node, hard or soft limit, what happens on breach</li><li>🧱 <strong>Componentes Clave</strong>: Gateway middleware, Redis counter store, algorithm (token bucket, sliding window log or counter)</li><li>⚡ <strong>Cuello de Botella Real</strong>: Distributed counting without a race condition, and Redis becoming the bottleneck</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: Token bucket or sliding window? What if Redis goes down? How do you handle clock skew?</li></ul><hr><h3 id="_3-design-pastebin" tabindex="-1">3. Design Pastebin <a class="header-anchor" href="#_3-design-pastebin" aria-label="Permalink to &quot;3. Design Pastebin&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Warm-up</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Text size limits, expiry, privacy, edit support, analytics</li><li>🧱 <strong>Componentes Clave</strong>: API, object storage for blobs, metadata database, cache, CDN</li><li>⚡ <strong>Cuello de Botella Real</strong>: Storing large text efficiently and separating blob from metadata</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: Where does the text actually live? How do you expire content? Custom URLs?</li></ul><hr><h3 id="_4-design-a-key-value-store" tabindex="-1">4. Design a key-value store <a class="header-anchor" href="#_4-design-a-key-value-store" aria-label="Permalink to &quot;4. Design a key-value store&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Core</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Consistency model, durability, single or distributed, size of values</li><li>🧱 <strong>Componentes Clave</strong>: Consistent hashing ring, replication, quorum reads and writes, gossip, Merkle trees</li><li>⚡ <strong>Cuello de Botella Real</strong>: Partitioning, replication and the consistency versus availability choice</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: How do you add a node? What is your replication factor? Handle a node failure mid-write.</li></ul><hr><h3 id="_5-design-a-web-crawler" tabindex="-1">5. Design a web crawler <a class="header-anchor" href="#_5-design-a-web-crawler" aria-label="Permalink to &quot;5. Design a web crawler&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Core</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Scale, politeness, freshness, content types, duplicate handling</li><li>🧱 <strong>Componentes Clave</strong>: URL frontier, fetcher pool, parser, duplicate detector, content store, scheduler</li><li>⚡ <strong>Cuello de Botella Real</strong>: Politeness (not overwhelming a host) and duplicate URL detection at billions of scale</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: How do you avoid crawler traps? Respect robots.txt? Detect duplicate content?</li></ul><hr><h3 id="_6-design-a-notification-system" tabindex="-1">6. Design a notification system <a class="header-anchor" href="#_6-design-a-notification-system" aria-label="Permalink to &quot;6. Design a notification system&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Core</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Channels (push, SMS, email), volume, priority, opt-out, delivery guarantees</li><li>🧱 <strong>Componentes Clave</strong>: API, notification service, message queue per channel, third-party adapters, template service, worker pool</li><li>⚡ <strong>Cuello de Botella Real</strong>: Third-party provider failure and avoiding duplicate sends</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: How do you handle a provider outage? Prevent duplicates? Support user preferences?</li></ul><hr><h3 id="_7-design-a-news-feed-facebook-twitter" tabindex="-1">7. Design a news feed (Facebook, Twitter) <a class="header-anchor" href="#_7-design-a-news-feed-facebook-twitter" aria-label="Permalink to &quot;7. Design a news feed (Facebook, Twitter)&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Core</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Feed ranking, follower counts, real-time expectations, media</li><li>🧱 <strong>Componentes Clave</strong>: Post service, fan-out service, feed cache, timeline store, ranking service, CDN</li><li>⚡ <strong>Cuello de Botella Real</strong>: Fan-out on write versus read, and celebrity users with 100 million followers</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: Push or pull? What about a user with 50 million followers? How do you rank?</li></ul><hr><h3 id="_8-design-a-chat-system-whatsapp-messenger" tabindex="-1">8. Design a chat system (WhatsApp, Messenger) <a class="header-anchor" href="#_8-design-a-chat-system-whatsapp-messenger" aria-label="Permalink to &quot;8. Design a chat system (WhatsApp, Messenger)&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Core</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: One-to-one or group, online presence, message history, media, delivery receipts</li><li>🧱 <strong>Componentes Clave</strong>: WebSocket servers, service discovery, message store, presence service, notification service</li><li>⚡ <strong>Cuello de Botella Real</strong>: Maintaining millions of persistent connections and message ordering</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: How do you route to the right WebSocket server? Handle offline users? Group of 500?</li></ul><hr><h3 id="_9-design-a-search-autocomplete-system" tabindex="-1">9. Design a search autocomplete system <a class="header-anchor" href="#_9-design-a-search-autocomplete-system" aria-label="Permalink to &quot;9. Design a search autocomplete system&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Core</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Latency budget, personalisation, spell correction, trending</li><li>🧱 <strong>Componentes Clave</strong>: Trie service, aggregation pipeline, cache layer, CDN for popular prefixes</li><li>⚡ <strong>Cuello de Botella Real</strong>: Sub-100ms latency and keeping the trie updated without downtime</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: How do you update the trie? Handle trending queries? Filter inappropriate suggestions?</li></ul><hr><h3 id="_10-design-a-video-streaming-service-youtube-netflix" tabindex="-1">10. Design a video streaming service (YouTube, Netflix) <a class="header-anchor" href="#_10-design-a-video-streaming-service-youtube-netflix" aria-label="Permalink to &quot;10. Design a video streaming service (YouTube, Netflix)&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Advanced</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Upload volume, resolutions, DRM, live or VOD, global reach</li><li>🧱 <strong>Componentes Clave</strong>: Upload service, transcoding pipeline, object storage, CDN, metadata service, recommendation service</li><li>⚡ <strong>Cuello de Botella Real</strong>: Transcoding cost and CDN strategy; storage and bandwidth dominate the bill</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: How does adaptive bitrate work? What does the CDN cost? Handle a viral video?</li></ul><hr><h3 id="_11-design-a-ride-hailing-service-uber-ola" tabindex="-1">11. Design a ride-hailing service (Uber, Ola) <a class="header-anchor" href="#_11-design-a-ride-hailing-service-uber-ola" aria-label="Permalink to &quot;11. Design a ride-hailing service (Uber, Ola)&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Advanced</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Matching latency, surge pricing, driver tracking frequency, payment</li><li>🧱 <strong>Componentes Clave</strong>: Location service with geospatial index, matching service, trip service, pricing, notification, payment</li><li>⚡ <strong>Cuello de Botella Real</strong>: Real-time geospatial matching and high-frequency location updates</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: How do you index locations? QuadTree or geohash? Match at 1000 requests per second?</li></ul><hr><h3 id="_12-design-a-food-delivery-system-swiggy-zomato" tabindex="-1">12. Design a food delivery system (Swiggy, Zomato) <a class="header-anchor" href="#_12-design-a-food-delivery-system-swiggy-zomato" aria-label="Permalink to &quot;12. Design a food delivery system (Swiggy, Zomato)&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Advanced</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Three-sided marketplace, ETA accuracy, real-time tracking, peak load</li><li>🧱 <strong>Componentes Clave</strong>: Search, order service, matching, tracking, restaurant service, payment, notification</li><li>⚡ <strong>Cuello de Botella Real</strong>: Peak-hour load concentration and three-party state consistency</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: What happens at 8pm on Friday? How do you compute ETA? Order fails mid-flight?</li></ul><hr><h3 id="_13-design-a-payment-system" tabindex="-1">13. Design a payment system <a class="header-anchor" href="#_13-design-a-payment-system" aria-label="Permalink to &quot;13. Design a payment system&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Advanced</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Idempotency, reconciliation, providers, currencies, compliance</li><li>🧱 <strong>Componentes Clave</strong>: Payment service, ledger, provider adapters, reconciliation job, webhook handler, fraud checks</li><li>⚡ <strong>Cuello de Botella Real</strong>: Exactly-once semantics with money, and reconciliation with external providers</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: The webhook fires twice. Now what? How do you reconcile? Handle a provider timeout?</li></ul><hr><h3 id="_14-design-a-ticket-booking-system-bookmyshow" tabindex="-1">14. Design a ticket booking system (BookMyShow) <a class="header-anchor" href="#_14-design-a-ticket-booking-system-bookmyshow" aria-label="Permalink to &quot;14. Design a ticket booking system (BookMyShow)&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Advanced</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Seat locking duration, concurrency at sale opening, payment timeout</li><li>🧱 <strong>Componentes Clave</strong>: Inventory service, seat locking (Redis with TTL), booking service, payment, notification</li><li>⚡ <strong>Cuello de Botella Real</strong>: Preventing double-booking under extreme concurrency at a popular release</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: Two users click the same seat simultaneously. Design the lock. What if payment times out?</li></ul><hr><h3 id="_15-design-a-distributed-cache" tabindex="-1">15. Design a distributed cache <a class="header-anchor" href="#_15-design-a-distributed-cache" aria-label="Permalink to &quot;15. Design a distributed cache&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Advanced</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Eviction policy, consistency, size, hot keys</li><li>🧱 <strong>Componentes Clave</strong>: Consistent hashing ring, LRU per node, replication, client library, invalidation channel</li><li>⚡ <strong>Cuello de Botella Real</strong>: Hot key distribution and invalidation across nodes</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: How do you handle a hot key? Invalidate across the cluster? Add a node without losing everything?</li></ul><hr><h3 id="_16-design-a-distributed-message-queue-kafka" tabindex="-1">16. Design a distributed message queue (Kafka) <a class="header-anchor" href="#_16-design-a-distributed-message-queue-kafka" aria-label="Permalink to &quot;16. Design a distributed message queue (Kafka)&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Advanced</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Ordering guarantees, durability, retention, consumer scaling</li><li>🧱 <strong>Componentes Clave</strong>: Brokers, partitioned append-only log, replication, consumer groups, offset store, coordinator</li><li>⚡ <strong>Cuello de Botella Real</strong>: Ordering versus parallelism, and rebalancing without duplicate processing</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: How do you guarantee ordering? What happens during a rebalance? Consumer crashes mid-batch?</li></ul><hr><h3 id="_17-design-google-docs-collaborative-editor" tabindex="-1">17. Design Google Docs (collaborative editor) <a class="header-anchor" href="#_17-design-google-docs-collaborative-editor" aria-label="Permalink to &quot;17. Design Google Docs (collaborative editor)&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Expert</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Number of concurrent editors, offline support, history, conflict handling</li><li>🧱 <strong>Componentes Clave</strong>: WebSocket layer, OT or CRDT engine, document store, presence service, version history</li><li>⚡ <strong>Cuello de Botella Real</strong>: Real-time conflict resolution with concurrent edits</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: OT or CRDT? Justify it. Handle offline edits reconciling on reconnect.</li></ul><hr><h3 id="_18-design-a-distributed-file-storage-dropbox-drive" tabindex="-1">18. Design a distributed file storage (Dropbox, Drive) <a class="header-anchor" href="#_18-design-a-distributed-file-storage-dropbox-drive" aria-label="Permalink to &quot;18. Design a distributed file storage (Dropbox, Drive)&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Advanced</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: File sizes, sync frequency, versioning, sharing, deduplication</li><li>🧱 <strong>Componentes Clave</strong>: Chunker, metadata service, block storage, sync service, notification service, dedup index</li><li>⚡ <strong>Cuello de Botella Real</strong>: Efficient delta sync and block-level deduplication</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: How do you sync only changes? Deduplicate across users? Handle conflicting edits?</li></ul><hr><h3 id="_19-design-a-proximity-service-yelp-nearby-places" tabindex="-1">19. Design a proximity service (Yelp, nearby places) <a class="header-anchor" href="#_19-design-a-proximity-service-yelp-nearby-places" aria-label="Permalink to &quot;19. Design a proximity service (Yelp, nearby places)&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Advanced</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Search radius, density variation, update frequency, ranking</li><li>🧱 <strong>Componentes Clave</strong>: Geospatial index (geohash or QuadTree), business service, search service, cache</li><li>⚡ <strong>Cuello de Botella Real</strong>: Geospatial indexing with wildly uneven density between cities and countryside</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: Geohash or QuadTree? Why? Handle dense city centres versus rural areas.</li></ul><hr><h3 id="_20-design-a-metrics-and-monitoring-system" tabindex="-1">20. Design a metrics and monitoring system <a class="header-anchor" href="#_20-design-a-metrics-and-monitoring-system" aria-label="Permalink to &quot;20. Design a metrics and monitoring system&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Advanced</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Cardinality, retention, query patterns, alerting latency</li><li>🧱 <strong>Componentes Clave</strong>: Collection agents, ingestion pipeline, time-series database, downsampling, query service, alerting</li><li>⚡ <strong>Cuello de Botella Real</strong>: Write volume and cardinality explosion; downsampling strategy</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: How do you handle 2 million writes per second? Store a year of data affordably?</li></ul><hr><h3 id="_21-design-a-logging-and-search-system-elk" tabindex="-1">21. Design a logging and search system (ELK) <a class="header-anchor" href="#_21-design-a-logging-and-search-system-elk" aria-label="Permalink to &quot;21. Design a logging and search system (ELK)&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Advanced</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Volume, retention, query latency, structured or unstructured</li><li>🧱 <strong>Componentes Clave</strong>: Log shippers, buffer (Kafka), indexing pipeline, search index, storage tiers, dashboard</li><li>⚡ <strong>Cuello de Botella Real</strong>: Indexing cost at volume and hot versus cold storage tiering</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: What does indexing 10TB a day cost? How do you tier old logs?</li></ul><hr><h3 id="_22-design-an-ad-click-aggregation-system" tabindex="-1">22. Design an ad click aggregation system <a class="header-anchor" href="#_22-design-an-ad-click-aggregation-system" aria-label="Permalink to &quot;22. Design an ad click aggregation system&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Expert</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Latency requirement, exactly-once, fraud, replay capability</li><li>🧱 <strong>Componentes Clave</strong>: Ingestion, Kafka, stream processor, aggregation store, reconciliation batch job, query service</li><li>⚡ <strong>Cuello de Botella Real</strong>: Exactly-once counting with money attached, plus late and duplicate events</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: How do you guarantee no double counting? Handle late events? Recompute after a bug?</li></ul><hr><h3 id="_23-design-a-recommendation-system" tabindex="-1">23. Design a recommendation system <a class="header-anchor" href="#_23-design-a-recommendation-system" aria-label="Permalink to &quot;23. Design a recommendation system&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Expert</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Cold start, latency, personalisation depth, feedback loop</li><li>🧱 <strong>Componentes Clave</strong>: Feature store, candidate generation, ranking model, serving layer, feedback pipeline, A/B framework</li><li>⚡ <strong>Cuello de Botella Real</strong>: Serving latency with a large model, and the cold-start problem</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: New user with no history? Serve in under 100ms? Measure whether it works?</li></ul><hr><h3 id="_24-design-a-stock-exchange-trading-system" tabindex="-1">24. Design a stock exchange / trading system <a class="header-anchor" href="#_24-design-a-stock-exchange-trading-system" aria-label="Permalink to &quot;24. Design a stock exchange / trading system&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Expert</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Latency budget, ordering guarantees, fairness, audit</li><li>🧱 <strong>Componentes Clave</strong>: Order gateway, matching engine, order book, market data feed, ledger, audit log</li><li>⚡ <strong>Cuello de Botella Real</strong>: Deterministic ordering at microsecond latency, and absolute correctness</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: Why a single-threaded matching engine? How do you guarantee fairness? Recover from a crash?</li></ul><hr><h3 id="_25-design-a-distributed-job-scheduler" tabindex="-1">25. Design a distributed job scheduler <a class="header-anchor" href="#_25-design-a-distributed-job-scheduler" aria-label="Permalink to &quot;25. Design a distributed job scheduler&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Advanced</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Scheduling precision, at-least-once or exactly-once, failure recovery</li><li>🧱 <strong>Componentes Clave</strong>: Scheduler service, job store, distributed lock, worker pool, retry queue, dead letter queue</li><li>⚡ <strong>Cuello de Botella Real</strong>: Ensuring a job runs exactly once across many scheduler instances</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: Two schedulers fire the same job. Prevent it. What if a worker dies mid-job?</li></ul><hr><h3 id="_26-design-a-leaderboard-system" tabindex="-1">26. Design a leaderboard system <a class="header-anchor" href="#_26-design-a-leaderboard-system" aria-label="Permalink to &quot;26. Design a leaderboard system&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Core</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Scale, update frequency, ranking window, tie handling</li><li>🧱 <strong>Componentes Clave</strong>: Redis sorted sets, sharded by region or bucket, aggregation service, cache</li><li>⚡ <strong>Cuello de Botella Real</strong>: Ranking millions of users in real time without recomputing</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: 10 million players updating constantly? Show a user their rank instantly?</li></ul><hr><h3 id="_27-design-an-api-rate-limited-public-api-platform" tabindex="-1">27. Design an API rate-limited public API platform <a class="header-anchor" href="#_27-design-an-api-rate-limited-public-api-platform" aria-label="Permalink to &quot;27. Design an API rate-limited public API platform&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Advanced</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Tiers, quotas, keys, analytics, abuse</li><li>🧱 <strong>Componentes Clave</strong>: API gateway, key service, quota store, rate limiter, analytics pipeline, developer portal</li><li>⚡ <strong>Cuello de Botella Real</strong>: Per-tenant quota enforcement across distributed gateways</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: How do you enforce quota across 20 gateway nodes? Handle a customer exceeding it?</li></ul><hr><h3 id="_28-design-a-url-content-moderation-system" tabindex="-1">28. Design a URL/content moderation system <a class="header-anchor" href="#_28-design-a-url-content-moderation-system" aria-label="Permalink to &quot;28. Design a URL/content moderation system&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Advanced</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Latency, accuracy, human review, appeals, scale</li><li>🧱 <strong>Componentes Clave</strong>: Ingestion, ML classifier, confidence routing, human review queue, appeals service, audit log</li><li>⚡ <strong>Cuello de Botella Real</strong>: Balancing false positives against latency, plus the human review bottleneck</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: What is your false positive tolerance? How do you handle appeals? Scale the human queue?</li></ul><hr><h3 id="_29-design-an-e-commerce-system-amazon-flipkart" tabindex="-1">29. Design an e-commerce system (Amazon, Flipkart) <a class="header-anchor" href="#_29-design-an-e-commerce-system-amazon-flipkart" aria-label="Permalink to &quot;29. Design an e-commerce system (Amazon, Flipkart)&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Advanced</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Catalogue size, inventory accuracy, cart persistence, peak sales events</li><li>🧱 <strong>Componentes Clave</strong>: Catalogue service, search, cart, inventory, order, payment, fulfilment, notification</li><li>⚡ <strong>Cuello de Botella Real</strong>: Inventory consistency during a flash sale and search at catalogue scale</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: Handle Big Billion Days traffic. Two users buy the last unit. Cart across devices?</li></ul><hr><h3 id="_30-design-a-hotel-or-flight-booking-system" tabindex="-1">30. Design a hotel or flight booking system <a class="header-anchor" href="#_30-design-a-hotel-or-flight-booking-system" aria-label="Permalink to &quot;30. Design a hotel or flight booking system&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Advanced</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Inventory sources, holds, cancellation, pricing volatility</li><li>🧱 <strong>Componentes Clave</strong>: Search service, inventory aggregator, hold service, booking, payment, supplier adapters</li><li>⚡ <strong>Cuello de Botella Real</strong>: Inventory held across third-party suppliers you do not control</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: The supplier says sold out after you took payment. Now what?</li></ul><hr><h3 id="_31-design-a-social-media-platform-instagram" tabindex="-1">31. Design a social media platform (Instagram) <a class="header-anchor" href="#_31-design-a-social-media-platform-instagram" aria-label="Permalink to &quot;31. Design a social media platform (Instagram)&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Advanced</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Media sizes, feed, stories, follower distribution, discovery</li><li>🧱 <strong>Componentes Clave</strong>: Upload service, media processing, object storage, CDN, feed service, graph service, search</li><li>⚡ <strong>Cuello de Botella Real</strong>: Media storage and delivery cost, plus feed generation for varied follower counts</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: How do you store and serve billions of images? Generate a feed for 100 followers versus 100 million?</li></ul><hr><h3 id="_32-design-a-url-based-analytics-system-google-analytics" tabindex="-1">32. Design a URL-based analytics system (Google Analytics) <a class="header-anchor" href="#_32-design-a-url-based-analytics-system-google-analytics" aria-label="Permalink to &quot;32. Design a URL-based analytics system (Google Analytics)&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Advanced</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Event volume, query flexibility, real-time versus batch, retention</li><li>🧱 <strong>Componentes Clave</strong>: Collection endpoint, Kafka, stream processing, OLAP store, query API, dashboard</li><li>⚡ <strong>Cuello de Botella Real</strong>: Ingestion at very high write rates with flexible aggregation queries</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: Real-time and historical in one system? How do you handle late-arriving events?</li></ul><hr><h3 id="_33-design-a-code-deployment-system" tabindex="-1">33. Design a code deployment system <a class="header-anchor" href="#_33-design-a-code-deployment-system" aria-label="Permalink to &quot;33. Design a code deployment system&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Advanced</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Rollout speed, rollback, canary, artifact storage, scale of fleet</li><li>🧱 <strong>Componentes Clave</strong>: Build service, artifact store, deployment orchestrator, health checker, rollback controller</li><li>⚡ <strong>Cuello de Botella Real</strong>: Safe progressive rollout with automated rollback on failure</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: Deploy to 10,000 servers safely. Detect a bad deploy automatically. Roll back in under a minute.</li></ul><hr><h3 id="_34-design-a-url-shortener-at-twitter-scale-deep-dive" tabindex="-1">34. Design a URL shortener at Twitter scale (deep dive) <a class="header-anchor" href="#_34-design-a-url-shortener-at-twitter-scale-deep-dive" aria-label="Permalink to &quot;34. Design a URL shortener at Twitter scale (deep dive)&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Advanced</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: The same problem, but with a hard latency SLA and global reach</li><li>🧱 <strong>Componentes Clave</strong>: Everything from the warm-up plus multi-region, edge caching and pre-generated keys</li><li>⚡ <strong>Cuello de Botella Real</strong>: Global latency and key generation across regions without coordination</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: Multi-region without conflicts? Sub-10ms redirects globally?</li></ul><hr><h3 id="_35-design-an-online-judge-coding-platform" tabindex="-1">35. Design an online judge / coding platform <a class="header-anchor" href="#_35-design-an-online-judge-coding-platform" aria-label="Permalink to &quot;35. Design an online judge / coding platform&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Advanced</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Language support, sandbox security, contest load spikes, fairness</li><li>🧱 <strong>Componentes Clave</strong>: Submission service, queue, sandboxed execution workers, verdict service, leaderboard, problem store</li><li>⚡ <strong>Cuello de Botella Real</strong>: Secure code sandboxing and contest-start load spikes</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: How do you sandbox untrusted code? Handle 50,000 submissions in the first minute?</li></ul><hr><h3 id="_36-design-an-llm-inference-serving-platform" tabindex="-1">36. Design an LLM inference serving platform <a class="header-anchor" href="#_36-design-an-llm-inference-serving-platform" aria-label="Permalink to &quot;36. Design an LLM inference serving platform&quot;">​</a></h3><p><strong>Nivel</strong>: <code>Expert</code></p><ul><li>❓ <strong>Aclarar Primero</strong>: Latency, model size, batching, cost, multi-tenancy</li><li>🧱 <strong>Componentes Clave</strong>: Gateway, request queue, batching layer, GPU worker pool, model store, cache, quota service</li><li>⚡ <strong>Cuello de Botella Real</strong>: GPU utilisation through batching, and cost per request</li><li>🔄 <strong>Preguntas de Seguimiento Habituales</strong>: How do you batch without hurting latency? Handle a 10x traffic spike on fixed GPUs?</li></ul><hr>',152)])])}const m=t(o,[["render",r]]);export{h as __pageData,m as default};
